const item = $input.first().json;
const headers = item.headers ?? {};
const provided = String(headers['x-n8n-secret'] ?? headers['X-N8N-Secret'] ?? '');
const expected = String($env.N8N_WEBHOOK_SECRET ?? '');
if (!expected) throw new Error('N8N_WEBHOOK_SECRET is not configured in n8n');
if (provided.length !== expected.length) throw new Error('Unauthorized: bad webhook secret');
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= provided.charCodeAt(i) ^ expected.charCodeAt(i);
if (diff !== 0) throw new Error('Unauthorized: bad webhook secret');
return [$input.first()];

const body = ($input.first().json.body ?? $input.first().json);
const out = [];
for (const p of (body.products ?? [])) {
  const facts = p.facts ?? [];
  const sourced = facts.filter(f => f.claim && f.source);
  let verdict = 'VERIFIED', reason = '';
  if (!p.name || !p.sourceUrl || !/^https?:\/\//.test(p.sourceUrl || '')) {
    verdict = 'REJECTED'; reason = 'missing name or valid sourceUrl';
  } else if (sourced.length < 2) {
    verdict = 'REJECTED'; reason = 'insufficient research (<2 sourced facts)';
  } else if (facts.some(f => f.claim && !f.source)) {
    verdict = 'NEEDS_REVIEW'; reason = 'unsourced claim present — never invent specs (§6)';
  }
  // §6 rules: no invented specs, no fake reviews, no false performance claims.
  out.push({ json: { product: { ...p, state: verdict === 'VERIFIED' ? 'VERIFIED' : p.state },
    verdict, reason } });
}
return out;

const j = $input.first().json;
return [{ json: { product: { ...j.product, state: 'VERIFIED',
  verifiedAt: new Date().toISOString() } } }];

const j = $input.first().json;
console.log('[verification] NEEDS_REVIEW', j.reason);
return [{ json: { product: { ...j.product, state: 'NEEDS_REVIEW' }, reason: j.reason } }];

const j = $input.first().json;
console.log('[verification] REJECTED', j.reason);
return [{ json: { product: { ...j.product, state: 'REJECTED' }, reason: j.reason } }];
